using System.Runtime.InteropServices;
namespace LSE.AutoCADElectrical.Librarian;
public static class Ace {
 public static dynamic Open(string path){if(!File.Exists(path))throw new FileNotFoundException("Access database was not found.",path);Type t=Type.GetTypeFromProgID("ADODB.Connection")??throw new InvalidOperationException("ADODB unavailable.");dynamic c=Activator.CreateInstance(t)!;var errors=new List<string>();foreach(string p in new[]{"Microsoft.ACE.OLEDB.16.0","Microsoft.ACE.OLEDB.12.0","Microsoft.Jet.OLEDB.4.0"})try{c.Open($"Provider={p};Data Source={path};Persist Security Info=False;");return c;}catch(Exception ex){errors.Add(p+": "+ex.Message);}Release(c);throw new InvalidOperationException("No 64-bit Access OLEDB provider could open "+path+Environment.NewLine+string.Join(Environment.NewLine,errors));}
 public static List<string> Tables(dynamic c){dynamic? r=null;try{r=c.OpenSchema(20);var x=new List<string>();while(!r.EOF){string n=Convert.ToString(r.Fields[2].Value)??"",k=Convert.ToString(r.Fields[3].Value)??"";if(k.Equals("TABLE",StringComparison.OrdinalIgnoreCase)&&!n.StartsWith("MSys",StringComparison.OrdinalIgnoreCase))x.Add(n);r.MoveNext();}return x;}finally{Release(r);}}
 public static void Exec(dynamic c,string sql){dynamic? r=null;try{r=c.Execute(sql);}finally{Release(r);}}
 public static string E(string v)=>v.Replace("'","''");
 public static void ValidateTable(string t){if(!System.Text.RegularExpressions.Regex.IsMatch(t,@"^[A-Za-z0-9_][A-Za-z0-9_ &/\.\-]*$"))throw new InvalidOperationException("Invalid table name: "+t);}
 public static void Release(object? o){if(o!=null&&Marshal.IsComObject(o))try{Marshal.FinalReleaseComObject(o);}catch{}}
 public static void Close(dynamic? c){if(c is null)return;try{c.Close();}catch{}Release(c);}
}
public sealed class FootprintLookupService {
 readonly string path; public FootprintLookupService(string p)=>path=p;
 public List<string> GetTables(){dynamic c=Ace.Open(path);try{return ((List<string>)Ace.Tables(c)).Where(n=>!n.StartsWith("_")).OrderBy(n=>n,StringComparer.OrdinalIgnoreCase).ToList();}finally{Ace.Close(c);}}
 public bool TableExists(string t){dynamic c=Ace.Open(path);try{return ((List<string>)Ace.Tables(c)).Any(n=>n.Equals(t,StringComparison.OrdinalIgnoreCase));}finally{Ace.Close(c);}}
 public void EnsureTable(string t){Ace.ValidateTable(t);if(TableExists(t))return;dynamic c=Ace.Open(path);try{Ace.Exec(c,$"CREATE TABLE [{t}] ([CATALOG] TEXT(60), [ASSEMBLYCODE] TEXT(24), [BLKNAM] TEXT(255), [DESCRIPTION] TEXT(150), [RECNUM] COUNTER)");}finally{Ace.Close(c);}}
 public string? Find(string t,string catalog){Ace.ValidateTable(t);dynamic c=Ace.Open(path);dynamic? r=null;try{r=c.Execute($"SELECT TOP 1 BLKNAM FROM [{t}] WHERE CATALOG='{Ace.E(catalog)}' AND ASSEMBLYCODE IS NULL");if((bool)r.EOF)return null;object v=r.Fields[0].Value;return v is null or DBNull?"":Convert.ToString(v);}finally{Ace.Release(r);Ace.Close(c);}}
 public void Upsert(string t,string catalog,string blkName,string description){Ace.ValidateTable(t);if(blkName.Length>255)throw new InvalidOperationException("Footprint path is longer than 255 characters (BLKNAM limit): "+blkName);if(description.Length>150)description=description[..150];dynamic c=Ace.Open(path);try{if(Find(t,catalog) is not null)Ace.Exec(c,$"UPDATE [{t}] SET [BLKNAM]='{Ace.E(blkName)}',[DESCRIPTION]='{Ace.E(description)}' WHERE CATALOG='{Ace.E(catalog)}' AND ASSEMBLYCODE IS NULL");else Ace.Exec(c,$"INSERT INTO [{t}] ([CATALOG],[BLKNAM],[DESCRIPTION]) VALUES ('{Ace.E(catalog)}','{Ace.E(blkName)}','{Ace.E(description)}')");}finally{Ace.Close(c);}}
 // Footprint mapping helpers. A "plain" row has no ASSEMBLYCODE (null or empty): the row AutoCAD Electrical uses for a single catalog number.
 const string Plain="(ASSEMBLYCODE IS NULL OR ASSEMBLYCODE='')"; public static string Key(string mfr,string cat)=>mfr.Trim()+"|"+cat.Trim();
 public string? ResolveTable(string mfr){Ace.ValidateTable(mfr);return GetTables().FirstOrDefault(n=>n.Equals(mfr.Trim(),StringComparison.OrdinalIgnoreCase));}
 public (int Rows,string BlkNam) FindPlain(string t,string catalog){Ace.ValidateTable(t);dynamic c=Ace.Open(path);dynamic? r=null;try{r=c.Execute($"SELECT BLKNAM FROM [{t}] WHERE CATALOG='{Ace.E(catalog)}' AND {Plain}");int n=0;string b="";while(!r.EOF){if(n==0){object v=r.Fields[0].Value;b=v is null or DBNull?"":Convert.ToString(v)??"";}n++;r.MoveNext();}return(n,b);}finally{Ace.Release(r);Ace.Close(c);}}
 // Updates every plain row of the catalog number, or inserts one (DESCRIPTION is only written on insert).
 public void SetMapping(string t,string catalog,string blkName,string description){Ace.ValidateTable(t);if(blkName.Length>255)throw new InvalidOperationException("Footprint path is longer than 255 characters (BLKNAM limit): "+blkName);if(description.Length>150)description=description[..150];int n=FindPlain(t,catalog).Rows;dynamic c=Ace.Open(path);try{if(n>0)Ace.Exec(c,$"UPDATE [{t}] SET [BLKNAM]='{Ace.E(blkName)}' WHERE CATALOG='{Ace.E(catalog)}' AND {Plain}");else Ace.Exec(c,$"INSERT INTO [{t}] ([CATALOG],[BLKNAM],[DESCRIPTION]) VALUES ('{Ace.E(catalog)}','{Ace.E(blkName)}','{Ace.E(description)}')");}finally{Ace.Close(c);}}
 // Plain-row BLKNAM for each (manufacturer, catalog) key that has one. Each involved manufacturer table is fetched once with Recordset.GetRows (a bulk transfer; an IN (...) list or per-cell COM reads are far slower on the 500,000-row stock tables) and filtered here. Keys: Key(mfr,cat).
 public Dictionary<string,string> ReadMappings(IEnumerable<(string Manufacturer,string Catalog)> keys){var x=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);dynamic c=Ace.Open(path);try{var tables=((List<string>)Ace.Tables(c)).Where(n=>!n.StartsWith("_")).ToHashSet(StringComparer.OrdinalIgnoreCase);
   foreach(var g in keys.Where(k=>k.Manufacturer.Trim().Length>0&&k.Catalog.Trim().Length>0).GroupBy(k=>k.Manufacturer.Trim(),StringComparer.OrdinalIgnoreCase)){string t=g.Key;if(!tables.Contains(t)||!System.Text.RegularExpressions.Regex.IsMatch(t,@"^[A-Za-z0-9_][A-Za-z0-9_ &/\.\-]*$"))continue;
    {var want=g.Select(k=>k.Catalog.Trim()).ToHashSet(StringComparer.OrdinalIgnoreCase);dynamic? r=null;try{r=c.Execute($"SELECT CATALOG,BLKNAM FROM [{t}] WHERE {Plain}");if(!(bool)r.EOF){Array a=(Array)r.GetRows();int f=a.GetLowerBound(0),r0=a.GetLowerBound(1),n=a.GetLength(1);for(int i=0;i<n;i++){string cat=(a.GetValue(f,r0+i) as string??"").Trim();if(!want.Contains(cat))continue;string b=a.GetValue(f+1,r0+i) as string??"";string k=Key(t,cat);if(!x.TryGetValue(k,out var old)||old.Length==0)x[k]=b;}}}finally{Ace.Release(r);}}}
   return x;}finally{Ace.Close(c);}}
 public List<(string Table,string Catalog,string BlkNam)> ReadAllPaths(){var x=new List<(string,string,string)>();dynamic c=Ace.Open(path);try{foreach(string t in ((List<string>)Ace.Tables(c)).Where(n=>!n.StartsWith("_"))){dynamic? r=null;try{r=c.Execute($"SELECT CATALOG,BLKNAM FROM [{t}]");while(!r.EOF){object v=r.Fields[1].Value;string b=v is null or DBNull?"":Convert.ToString(v)??"";if(b.Length>0)x.Add((t,Convert.ToString(r.Fields[0].Value)??"",b));r.MoveNext();}}catch{}finally{Ace.Release(r);}}return x;}finally{Ace.Close(c);}}
}
// default_cat.mdb: one table per AutoCAD Electrical family (FU, CB, PB, ...). The LSE part number lives in the column
// named by AppSettings.LsePartColumn (USER1). Reads scan every family table because a prefix can be issued in any of them.
public sealed class CatalogService {
 readonly string path; public CatalogService(string p)=>path=p; public string Path=>path;
 static readonly string[] Writable={"CATALOG","MANUFACTURER","DESCRIPTION","TYPE","RATING","VOLTAGE","USER1","USER2","USER3","TEXTVALUE","WEBLINK","WDBLKNAM"};
 public static void ValidateColumn(string c){if(!System.Text.RegularExpressions.Regex.IsMatch(c,@"^[A-Za-z][A-Za-z0-9_]{0,63}$"))throw new InvalidOperationException("Invalid column name: "+c);}
 public List<string> GetTables(){dynamic c=Ace.Open(path);try{return ((List<string>)Ace.Tables(c)).Where(n=>!n.StartsWith("_")).OrderBy(n=>n,StringComparer.OrdinalIgnoreCase).ToList();}finally{Ace.Close(c);}}
 public Dictionary<string,string> GetFamilyDescriptions(){var x=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);dynamic c=Ace.Open(path);dynamic? r=null;try{r=c.Execute("SELECT FAMILY,[DESC] FROM [_FAMILY_DESCRIPTION]");while(!r.EOF){string f=Convert.ToString(r.Fields[0].Value)??"";object v=r.Fields[1].Value;if(f.Trim().Length>0)x[f.Trim()]=v is null or DBNull?"":Convert.ToString(v)?.Trim()??"";r.MoveNext();}}catch{}finally{Ace.Release(r);Ace.Close(c);}return x;}
 // column name -> defined size (0 = memo/unknown)
 public Dictionary<string,int> GetColumns(string table){Ace.ValidateTable(table);var x=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);dynamic c=Ace.Open(path);dynamic? r=null;try{r=c.Execute($"SELECT TOP 1 * FROM [{table}]");for(int i=0;i<r.Fields.Count;i++){dynamic f=r.Fields[i];string n=Convert.ToString(f.Name)??"";int size=0;try{size=Convert.ToInt32(f.DefinedSize);}catch{}if(size<0||size>10000)size=0;x[n]=size;}}finally{Ace.Release(r);Ace.Close(c);}return x;}
 // Every value of [column] that starts with prefix, with the family table it sits in, across all family tables.
 public List<(string Value,string Table)> ReadColumnStartingWith(string column,string prefix){ValidateColumn(column);var x=new List<(string,string)>();dynamic c=Ace.Open(path);try{foreach(string t in ((List<string>)Ace.Tables(c)).Where(n=>!n.StartsWith("_"))){dynamic? r=null;try{r=c.Execute($"SELECT [{column}] FROM [{t}] WHERE [{column}] LIKE '{Ace.E(prefix)}%'");while(!r.EOF){object v=r.Fields[0].Value;if(v is not null and not DBNull){string s=Convert.ToString(v)??"";if(s.Trim().Length>0)x.Add((s.Trim(),t));}r.MoveNext();}}catch{}finally{Ace.Release(r);}}return x;}finally{Ace.Close(c);}}
 // Every row that carries an LSE part number (partColumn not empty), with its family table. Read only; tables without the column are skipped.
 public List<(string Table,string Manufacturer,string Catalog,string Part,string Description)> ReadParts(string partColumn){ValidateColumn(partColumn);var x=new List<(string,string,string,string,string)>();dynamic c=Ace.Open(path);try{foreach(string t in ((List<string>)Ace.Tables(c)).Where(n=>!n.StartsWith("_"))){dynamic? r=null;try{r=c.Execute($"SELECT MANUFACTURER,CATALOG,[{partColumn}],DESCRIPTION FROM [{t}] WHERE [{partColumn}] IS NOT NULL AND [{partColumn}]<>''");while(!r.EOF){string S(int i){object v=r.Fields[i].Value;return v is null or DBNull?"":(Convert.ToString(v)??"").Trim();}x.Add((t,S(0),S(1),S(2),S(3)));r.MoveNext();}}catch{}finally{Ace.Release(r);}}return x;}finally{Ace.Close(c);}}
 public List<string> ReadDistinct(string table,string column){Ace.ValidateTable(table);ValidateColumn(column);var x=new List<string>();dynamic c=Ace.Open(path);dynamic? r=null;try{r=c.Execute($"SELECT DISTINCT [{column}] FROM [{table}] WHERE [{column}] IS NOT NULL ORDER BY [{column}]");while(!r.EOF){string s=Convert.ToString(r.Fields[0].Value)?.Trim()??"";if(s.Length>0)x.Add(s);r.MoveNext();}}catch{}finally{Ace.Release(r);Ace.Close(c);}return x;}
 // Whole rows for the catalog browser: every column as a trimmed string, capped at limit rows. FindByKey takes CatalogRecord.Key (TABLE|MANUFACTURER|CATALOG).
 public List<CatalogRecord> ReadTable(string table,int limit=20000){Ace.ValidateTable(table);return Query(table,$"SELECT TOP {Math.Max(1,limit)} * FROM [{table}]");}
 public CatalogRecord? FindByKey(string key){var p=key.Split('|');if(p.Length<3)return null;Ace.ValidateTable(p[0]);return Query(p[0],$"SELECT TOP 1 * FROM [{p[0]}] WHERE MANUFACTURER='{Ace.E(p[1])}' AND CATALOG='{Ace.E(string.Join("|",p.Skip(2)))}'").FirstOrDefault();}
 List<CatalogRecord> Query(string table,string sql){var x=new List<CatalogRecord>();dynamic c=Ace.Open(path);dynamic? r=null;try{r=c.Execute(sql);var names=new List<string>();for(int i=0;i<r.Fields.Count;i++)names.Add(Convert.ToString(r.Fields[i].Name)??"");while(!r.EOF){var z=new CatalogRecord{TableName=table};for(int i=0;i<names.Count;i++){object v=r.Fields[i].Value;z.Values[names[i]]=v is null or DBNull?"":Convert.ToString(v)?.Trim()??"";}x.Add(z);r.MoveNext();}}finally{Ace.Release(r);Ace.Close(c);}return x;}
 public bool Exists(string table,string mfg,string cat){Ace.ValidateTable(table);dynamic c=Ace.Open(path);dynamic? r=null;try{r=c.Execute($"SELECT TOP 1 CATALOG FROM [{table}] WHERE MANUFACTURER='{Ace.E(mfg)}' AND CATALOG='{Ace.E(cat)}'");return !(bool)r.EOF;}finally{Ace.Release(r);Ace.Close(c);}}
 public (string Table,string Manufacturer,string Catalog)? FindByColumn(string column,string value){ValidateColumn(column);dynamic c=Ace.Open(path);try{foreach(string t in ((List<string>)Ace.Tables(c)).Where(n=>!n.StartsWith("_"))){dynamic? r=null;try{r=c.Execute($"SELECT TOP 1 MANUFACTURER,CATALOG FROM [{t}] WHERE [{column}]='{Ace.E(value)}'");if(!(bool)r.EOF)return(t,Convert.ToString(r.Fields[0].Value)??"",Convert.ToString(r.Fields[1].Value)??"");}catch{}finally{Ace.Release(r);}}return null;}finally{Ace.Close(c);}}
 // Inserts one row. Only columns the table really has are written; the part number goes into partColumn.
 public void AddRecord(CatalogAddRequest q,string partColumn){Ace.ValidateTable(q.TableName);ValidateColumn(partColumn);var cols=GetColumns(q.TableName);if(!cols.ContainsKey(partColumn))throw new InvalidOperationException($"Table {q.TableName} has no {partColumn} column, so it cannot hold an LSE part number.");
  var values=new List<(string Column,string Value)>{("CATALOG",q.Catalog),("MANUFACTURER",q.Manufacturer),("DESCRIPTION",q.Description),("TYPE",q.Type),("RATING",q.Rating),("VOLTAGE",q.Voltage),(partColumn,q.User1),("USER2",q.User2),("USER3",q.User3),("TEXTVALUE",q.TextValue),("WEBLINK",q.WebLink),("WDBLKNAM",q.WdBlkNam)};
  if(!partColumn.Equals("USER1",StringComparison.OrdinalIgnoreCase))values.RemoveAll(v=>v.Column.Equals("USER1",StringComparison.OrdinalIgnoreCase)&&v.Value.Length==0);
  var use=values.Where(v=>cols.ContainsKey(v.Column)&&v.Value.Length>0).GroupBy(v=>v.Column,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();
  foreach(var (col,val) in use){int size=cols[col];if(size>0&&val.Length>size)throw new InvalidOperationException($"{col} is {val.Length} characters; the catalog column holds {size}.");}
  if(!use.Any(v=>v.Column.Equals(partColumn,StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("The part number is empty.");
  dynamic c=Ace.Open(path);try{Ace.Exec(c,$"INSERT INTO [{q.TableName}] ({string.Join(",",use.Select(v=>$"[{v.Column}]"))}) VALUES ({string.Join(",",use.Select(v=>$"'{Ace.E(v.Value)}'"))})");}finally{Ace.Close(c);}}
 // WDBLKNAM of every LSE part row, keyed Table|part number. Read only; tables without a WDBLKNAM column are skipped.
 public Dictionary<string,string> ReadSymbols(string partColumn){ValidateColumn(partColumn);var x=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);dynamic c=Ace.Open(path);try{foreach(string t in ((List<string>)Ace.Tables(c)).Where(n=>!n.StartsWith("_"))){dynamic? r=null;try{r=c.Execute($"SELECT [{partColumn}],WDBLKNAM FROM [{t}] WHERE [{partColumn}] IS NOT NULL AND [{partColumn}]<>''");while(!r.EOF){object p=r.Fields[0].Value,v=r.Fields[1].Value;string part=p is null or DBNull?"":(Convert.ToString(p)??"").Trim();if(part.Length>0)x[t+"|"+part]=v is null or DBNull?"":(Convert.ToString(v)??"").Trim();r.MoveNext();}}catch{}finally{Ace.Release(r);}}return x;}finally{Ace.Close(c);}}
 // The rows matching table + part number column + MANUFACTURER + CATALOG: how many, and the WDBLKNAM of the first. Throws when the table has no WDBLKNAM column.
 public (int Rows,string Symbol) FindSymbolRows(string table,string partColumn,string part,string mfg,string cat){Ace.ValidateTable(table);ValidateColumn(partColumn);if(!GetColumns(table).ContainsKey("WDBLKNAM"))throw new InvalidOperationException($"Family table {table} has no WDBLKNAM column.");dynamic c=Ace.Open(path);dynamic? r=null;try{r=c.Execute($"SELECT WDBLKNAM FROM [{table}] WHERE [{partColumn}]='{Ace.E(part)}' AND MANUFACTURER='{Ace.E(mfg)}' AND CATALOG='{Ace.E(cat)}'");int n=0;string s="";while(!r.EOF){if(n==0){object v=r.Fields[0].Value;s=v is null or DBNull?"":(Convert.ToString(v)??"").Trim();}n++;r.MoveNext();}return(n,s);}finally{Ace.Release(r);Ace.Close(c);}}
 // Updates WDBLKNAM and nothing else on the one row that matches table + part number column + MANUFACTURER + CATALOG.
 public void SetSymbol(string table,string partColumn,string part,string mfg,string cat,string symbol){Ace.ValidateTable(table);ValidateColumn(partColumn);int size=GetColumns(table).TryGetValue("WDBLKNAM",out int z)?z:throw new InvalidOperationException($"Family table {table} has no WDBLKNAM column.");if(size>0&&symbol.Length>size)throw new InvalidOperationException($"WDBLKNAM is {symbol.Length} characters; the catalog column holds {size}.");dynamic c=Ace.Open(path);try{Ace.Exec(c,$"UPDATE [{table}] SET [WDBLKNAM]='{Ace.E(symbol)}' WHERE [{partColumn}]='{Ace.E(part)}' AND MANUFACTURER='{Ace.E(mfg)}' AND CATALOG='{Ace.E(cat)}'");}finally{Ace.Close(c);}}
 // category code -> family tables that already hold standard-form part numbers with that code, most used first
 public Dictionary<string,List<string>> FamilyHints(NamingFormat f){var counts=new Dictionary<string,Dictionary<string,int>>(StringComparer.Ordinal);var form=PartNumberService.StandardForm(f);foreach(var (v,t) in ReadColumnStartingWith("USER1","")){string pn=PartNumberService.Normalize(v);if(!form.IsMatch(pn))continue;string cat=pn[..f.CategoryChars];if(!counts.TryGetValue(cat,out var d))counts[cat]=d=new(StringComparer.OrdinalIgnoreCase);d[t]=d.TryGetValue(t,out int k)?k+1:1;}return counts.OrderBy(p=>p.Key,StringComparer.Ordinal).ToDictionary(p=>p.Key,p=>p.Value.OrderByDescending(q=>q.Value).ThenBy(q=>q.Key,StringComparer.OrdinalIgnoreCase).Take(3).Select(q=>q.Key).ToList(),StringComparer.OrdinalIgnoreCase);}
}
// Serialises part-number issuance between workstations (same lock file name as the Inventor add-in, next to the catalog).
public sealed class IssuanceLock:IDisposable{
 FileStream? f; public static string PathFor(string catalogPath)=>System.IO.Path.Combine(System.IO.Path.GetDirectoryName(catalogPath)??"","LSE_PartNumber.lock");
 public static IssuanceLock Acquire(string catalogPath,List<string> log){string p=PathFor(catalogPath);var x=new IssuanceLock();for(int i=0;i<40;i++){try{x.f=new FileStream(p,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None,4096,FileOptions.DeleteOnClose);byte[] b=System.Text.Encoding.UTF8.GetBytes($"{Environment.UserName}@{Environment.MachineName} {DateTime.Now:s}");x.f.Write(b,0,b.Length);x.f.Flush();log.Add("Part number issuance lock: PASS");return x;}catch(IOException){Thread.Sleep(250);}}throw new InvalidOperationException("Another workstation is issuing a part number right now (lock file "+p+"). Try again in a moment.");}
 public void Dispose(){try{f?.Dispose();}catch{}f=null;}
}
